[{"order":1,"type":"heading","text":"Understanding Middleware and the Next Function in Express.js"},{"order":2,"type":"paragraph","text":"Middleware functions are the backbone of any Express.js application. They are functions that have access to the request object (req), the response object (res), and the next middleware function in the application's request-response cycle."},{"order":3,"type":"subheading","text":"What is Middleware?"},{"order":4,"type":"paragraph","text":"Think of middleware as a pipeline of processing steps that an incoming HTTP request must pass through before reaching your final route handler. Common use cases include logging requests, parsing JSON bodies, authenticating users, and handling errors."},{"order":5,"type":"subheading","text":"The Role of the Next Function"},{"order":6,"type":"paragraph","text":"The next function is a callback function in the Express router which, when invoked, executes the middleware succeeding the current middleware. If the current middleware function does not end the request-response cycle, it must call next() to pass control to the next middleware function. Otherwise, the request will hang."},{"order":7,"type":"subheading","text":"Creating Custom Middleware"},{"order":8,"type":"paragraph","text":"Below is a simple example of a custom logging middleware that records the HTTP method, URL, and timestamp of every incoming request."},{"order":9,"type":"code","text":"const express = require('express');
const app = express();

const requestLogger = (req, res, next) => {
  console.log('[METHOD]: ' + req.method + ' | [URL]: ' + req.url + ' | [TIME]: ' + new Date().toISOString());
  next();
};

app.use(requestLogger);

app.get('/', (req, res) => {
  res.send('Hello World!');
});

app.listen(3000, () => {
  console.log('Server is running on port 3000');
});"},{"order":10,"type":"subheading","text":"Key Takeaways"},{"order":11,"type":"bullet_point","text":"Middleware executes sequentially in the order they are loaded using app.use() or route definitions."},{"order":12,"type":"bullet_point","text":"Always invoke next() to prevent request hanging, unless you are sending a response directly from the middleware (e.g., res.send())."},{"order":13,"type":"bullet_point","text":"Passing an error to the next function (e.g., next(new Error('Something went wrong'))) will skip all normal middleware and jump straight to error-handling middleware."}]
